#!/usr/bin/env node
// Regenerates src/desks/builtin-assets.gen.ts: the text of desks.default.yaml and
// roles/*.md, embedded so single-file builds (the bun-compiled binary and the
// PyPI _vendor/ach.mjs bundle) can run `ach desk up` with no sibling files.
// tests/desks-builtin-assets.test.ts fails when the generated file drifts.
// Usage: node scripts/gen-desks-assets.mjs [--check]
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const out = join(root, "src", "desks", "builtin-assets.gen.ts");

export function renderDeskAssets(repoRoot = root) {
  const files = { "desks.default.yaml": readFileSync(join(repoRoot, "desks.default.yaml"), "utf8") };
  for (const f of readdirSync(join(repoRoot, "roles")).filter((n) => n.endsWith(".md")).sort()) {
    files[`roles/${f}`] = readFileSync(join(repoRoot, "roles", f), "utf8");
  }
  const body = Object.entries(files)
    .map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`)
    .join("\n");
  return `// GENERATED by scripts/gen-desks-assets.mjs from desks.default.yaml and roles/*.md. Do not edit.
// Run \`npm run gen:desks-assets\` after changing those files.
export const BUILTIN_DESK_ASSETS: Record<string, string> = {
${body}
};
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const text = renderDeskAssets();
  if (process.argv.includes("--check")) {
    const cur = (() => { try { return readFileSync(out, "utf8"); } catch { return ""; } })();
    if (cur !== text) { console.error(`stale: ${out}; run npm run gen:desks-assets`); process.exit(1); }
    console.log("desks assets up to date");
  } else {
    writeFileSync(out, text);
    console.log(`wrote ${out}`);
  }
}
